const fmt=(v,n=1)=>Number.isFinite(v)?v.toLocaleString('en-GB',{maximumFractionDigits:n,minimumFractionDigits:n}):'—';
const signed=(v,n=1)=>{if(Math.abs(v)<.5*10**-n)v=0;return(v>0?'+':v<0?'−':'')+fmt(Math.abs(v),n);};
let profiles=[],evidence={},validation={},original={},diffusionAudit={},turnoverAudit={},foreignFrontiers={},sizeDiagnostics={},employmentAudit={},priceAudit={},openEconomyAudit={},moneyAudit={},fiscalAudit={},tradeAudit={},financeAudit={},liveAudit={},distributionAudit={},householdBenchmarks={},tariffAudit={},capitalBenchmarks={},capitalAudit={},governmentBenchmarks={},fiscalIncomeAudit={},societyBenchmarks={},societyAudit={},foreignProjectionAudit={},eventInputAudit={},macroPolicyAudit={},employmentPopulationBenchmarks={},socialSpendingAudit={},globalAudit={},macroExternalAudit={},tradeBidAudit={},sensitivityResult=null,pendingTask='experiment',worker=null,pending=null,result=null,advanced=false,scale='index',metric='output',selectedTime=40,playTimer=null,positions=[],editorExpanded=true;
