$('#agent-canvas').onpointermove=e=>{if(!result)return;let r=e.target.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,p=positions.filter(p=>Math.hypot(p.x-x,p.y-y)<p.r+7).sort((a,b)=>Math.hypot(a.x-x,a.y-y)-Math.hypot(b.x-x,b.y-y))[0];$('#firm-detail').textContent=p?`Firm ${p.firm.id+1} · born ${p.firm.birthTime===0?'initial cohort':'period '+p.firm.birthTime} · exit risk ${fmt(100*p.firm.exitProbability,1)}% · foreign source ${p.firm.foreignSource??'none this step'} · technology ${fmt(p.firm.a,3)} · productive capital ${fmt(p.firm.capital,2)} real units · output ${fmt(p.firm.output,2)} · jobs ${fmt(p.firm.employment,2)} · loans ${fmt(p.firm.loan,2)} · cash ${fmt(p.firm.cash,2)}`:'Hover over a firm to inspect its balance sheet.';};
